// Renderer-independent construction anchors. Distances and positions are metres.
import {facadePoint,facadeNormal} from './grammar-surfaces.js';
import {seedHash} from '../hull/surface.js';
export const ENVIRONMENT_VERSION=1;
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
export function environmentOptions(input={}){const value=(v,d)=>Number.isFinite(Number(v))?Number(v):d;return{enabled:input.enabled!==false,detail:clamp(value(input.detail,.7),0,1.5),weather:clamp(value(input.weather,1),0,2),seed:Number(input.seed??417)>>>0};}
export function climateWeather(style='garden'){return structuredClone(({arid:{rain:.05,dust:.75,wetness:0,biology:0},ocean:{rain:.7,dust:.1,wetness:.15,biology:.2},lunar:{rain:0,dust:.5,wetness:0,biology:0},glacial:{rain:.15,dust:.08,wetness:.04,biology:0}})[style]||{rain:.35,dust:.2,wetness:0,biology:.08});}
export function surfacePatterns(recipe,atlas={columns:1,rows:1}){if(recipe?.zones)return recipe.zones.map(z=>[z.panelsX,z.panelsY]);if(recipe?.nodes){const nodes=new Map(recipe.nodes.map(n=>[n.id,n])),out=recipe.nodes.find(n=>n.kind==='output');function visit(id){const n=nodes.get(id);if(!n)return null;if(n.kind==='building'){const z=n.params.recipe.zones[n.params.zone||0];return[z.panelsX,z.panelsY];}if(n.kind==='buildingStage'||n.kind==='weather'){const e=recipe.edges.find(e=>e.target===n.id&&e.targetHandle==='in'),base=visit(e?.source);if(!base)return null;if(n.kind==='buildingStage'&&n.params.enabled!==false){base[0]=n.params.values.panelsX??base[0];base[1]=n.params.values.panelsY??base[1];}return base;}return null;}const edge=recipe.edges.find(e=>e.target===out?.id),p=visit(edge?.source);if(p)return[p];}return undefined;}
export function assemblyContext(){return{ground:0,leaks:[{point:[1,3.98,.19],normal:[0,0,1],length:3.8,width:.075}],shelters:[{center:[0,3.8,.45],half:[4.4,.12,.65]}],repairs:[{point:[-1.5,1.6,.15],normal:[0,0,1],radius:.55,aspect:1.5}],contacts:[{center:[0,0,0],half:[4.2,.2,.25]},{center:[-4,0,2],half:[.25,.2,2.2]}]};}
export function grammarContext(ir){const facades=ir.facades||[],rank=f=>seedHash(ir.options.seed+':weather:'+f.id),candidates=facades.filter(f=>f.zone==='crown'||f.type==='vent'||f.type==='service').sort((a,b)=>rank(a)-rank(b)),leaks=candidates.slice(0,6).map(f=>({point:facadePoint(f,0,f.height*.93,.03),normal:facadeNormal(f,0,f.height*.93),length:Math.min(9,f.position[1]+f.height),width:.045+(rank(f)%80)/1000})),repairs=facades.filter(f=>f.type==='solid'||f.type==='service').sort((a,b)=>rank(a)-rank(b)).slice(0,3).map(f=>({point:facadePoint(f,f.width*.15,f.height*.43,.035),normal:facadeNormal(f,0,f.height*.43),radius:.3+(rank(f)%35)/100,aspect:1.4}));const shelters=(ir.roofs||[]).filter(r=>r.equipment).slice(0,4).map(r=>({center:[r.cx,r.y-.18,r.cz],half:[ir.options.bay*.52,.15,ir.options.bay*.52]}));const ep=facades.find(f=>f.id===ir.entry)?.position||[0,0,0];const contacts=facades.filter(f=>f.floor===0).sort((a,b)=>Math.hypot(a.position[0]-ep[0],a.position[2]-ep[2])-Math.hypot(b.position[0]-ep[0],b.position[2]-ep[2])).slice(0,8).map(f=>({center:facadePoint(f,0,0,0),half:[Math.abs(f.n[0])>.7?.35:f.width*.52,.25,Math.abs(f.n[0])>.7?f.width*.52:.35]}));return{ground:0,leaks,shelters,repairs,contacts};}
export function transformContext(input,angle=0,offset=[0,0,0]){const c=validateContext(input),co=Math.cos(angle),si=Math.sin(angle),rotate=v=>[v[0]*co+v[2]*si,v[1],v[2]*co-v[0]*si];for(const key of ['leaks','repairs','shelters','contacts'])for(const f of c[key]){const field=f.point?'point':'center';f[field]=rotate(f[field]).map((v,i)=>v+offset[i]);if(f.normal)f.normal=rotate(f.normal);if(f.half){const h=f.half;f.half=[Math.abs(co)*h[0]+Math.abs(si)*h[2],h[1],Math.abs(si)*h[0]+Math.abs(co)*h[2]];}}c.ground+=offset[1];return c;}
export function validateContext(input={}){const vec=v=>Array.isArray(v)&&v.length===3&&v.every(Number.isFinite),out={ground:Number.isFinite(input.ground)?input.ground:0};for(const key of ['leaks','shelters','repairs','contacts']){const list=input[key]||[];if(!Array.isArray(list)||list.length>8)throw Error('Surface context supports up to eight '+key);out[key]=list.map(f=>{if(!vec(f.point||f.center)||!vec(f.normal||f.half))throw Error('Invalid surface context anchor');if(f.half&&f.half.some(v=>v<=0))throw Error('Surface context bounds must be positive');if(f.normal&&(Math.hypot(...f.normal)<.9||Math.hypot(...f.normal)>1.1))throw Error('Invalid anchor normal');if(key==='leaks'&&(!Number.isFinite(f.length)||!Number.isFinite(f.width)||!(f.length>0)||!(f.width>0)))throw Error('Invalid runoff extent');if(key==='repairs'&&(!Number.isFinite(f.radius)||!Number.isFinite(f.aspect)||!(f.radius>0)||!(f.aspect>0)))throw Error('Invalid repair extent');return structuredClone(f);});}return out;}
// Reference masks for seam/translation tests. Does not claim fluid simulation.
export function contextMasks(input,p,n=[0,0,1]){const c=validateContext(input);let leak=0,shelter=0,repair=0,contact=0;for(const f of c.leaks){const h=f.point[1]-p[1],d=Math.hypot(p[0]-f.point[0],p[2]-f.point[2]),facing=Math.max(0,n.reduce((s,v,i)=>s+v*f.normal[i],0));if(h>=0&&h<f.length)leak=Math.max(leak,Math.exp(-d*d/(2*(f.width+h*.018)**2))*(1-h/f.length)*facing);}for(const f of c.shelters){const dx=Math.abs(p[0]-f.center[0])-f.half[0],dz=Math.abs(p[2]-f.center[2])-f.half[2];if(p[1]<f.center[1]&&p[1]>f.center[1]-3)shelter=Math.max(shelter,clamp(1-Math.max(dx,dz)/.25));}for(const f of c.repairs){const d=p.map((v,i)=>v-f.point[i]),depth=Math.abs(d.reduce((s,v,i)=>s+v*f.normal[i],0)),r=Math.hypot(d[0],d[2],d[1]*f.aspect)/f.radius;if(depth<.12)repair=Math.max(repair,clamp((1-r)*8));}for(const f of c.contacts){const d=Math.hypot(Math.max(0,Math.abs(p[0]-f.center[0])-f.half[0]),Math.max(0,Math.abs(p[2]-f.center[2])-f.half[2]));contact=Math.max(contact,clamp(1-d/.8)*clamp(1-Math.abs(p[1]-c.ground)/.65));}return{leak,shelter,repair,contact};}
